    out = [row[:] for row in grid]
    # Locate a color appearing as a two-pixel diagonal; extend that diagonal.
    candidates = []
    h, w = len(grid), len(grid[0])
    for color in range(2, 10):
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for r, c in pts:
            for dc in (-1, 1):
                if (r+1, c+dc) in pts:
                    candidates.append((color, r+1, c+dc, dc))
    if candidates:
        # Use the pair whose second marker is lowest; ties prefer the marker
        # furthest toward the left, matching the diagonal object to continue.
        color, r, c, dc = max(candidates, key=lambda p: (p[1], -p[2]))
        while 0 <= r+1 < h and 0 <= c+dc < w:
            r += 1
            c += dc
            out[r][c] = color
    return out
"
